import React from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { BarChart3, Bell, Boxes, CreditCard, FileText, Home, LogOut, Package, Receipt, ShoppingCart, UserRound, Users } from 'lucide-react';
import { useAuth } from '../auth/hooks/useAuth';

const items = [['Inicio', '/vendedor/inicio', Home], ['Nueva venta', '/vendedor/venta', ShoppingCart], ['Mis ventas', '/vendedor/ventas', BarChart3], ['Cotizaciones', '/vendedor/cotizaciones', FileText], ['Solicitudes', '/vendedor/aprobaciones', Bell], ['Pedidos', '/vendedor/pedidos', Boxes], ['Clientes', '/vendedor/clientes', Users], ['Gastos', '/vendedor/gastos', Receipt], ['Catálogo', '/vendedor/catalogo', Package], ['Inventario', '/vendedor/inventario', Boxes], ['Crédito', '/vendedor/credito', CreditCard], ['Comisión', '/vendedor/comision', UserRound]] as const;
const mobileItems = items.filter(([label]) => ['Inicio', 'Nueva venta', 'Mis ventas', 'Clientes', 'Gastos', 'Catálogo', 'Inventario', 'Comisión'].includes(label));

export const VendorLayout: React.FC = () => {
  const { profile, sucursalActiva, signOut } = useAuth(); const location = useLocation(); const navigate = useNavigate();
  const logout = async () => { await signOut(); navigate('/login'); };
  return <div className="min-h-screen bg-[#f7f7f5] text-gray-900"><aside className="fixed inset-y-0 left-0 hidden w-60 border-r border-gray-200 bg-white md:flex md:flex-col"><div className="flex h-16 items-center border-b border-gray-200 px-5"><span className="text-lg font-semibold tracking-[0.18em] text-gray-950">ALTIX</span><span className="ml-auto text-[10px] uppercase tracking-wide text-gray-400">Venta</span></div><nav className="flex-1 overflow-y-auto px-3 py-4">{items.map(([label, path, Icon]) => <Link key={path} to={path} className={`flex items-center gap-3 border-l-2 px-3 py-2 text-sm ${location.pathname === path ? 'border-blue-600 bg-blue-50 font-medium text-blue-700' : 'border-transparent text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}><Icon size={16} />{label}</Link>)}</nav><div className="flex items-center justify-between border-t border-gray-200 p-4"><div className="min-w-0 pr-2"><p className="truncate text-sm font-medium">{profile?.nombre_completo}</p><p className="truncate text-xs text-gray-500">{sucursalActiva?.nombre ?? 'Sin sucursal'}</p></div><button onClick={logout} title="Cerrar sesión" className="p-2 text-gray-400 hover:bg-gray-100 hover:text-gray-900"><LogOut size={17} /></button></div></aside><div className="min-h-screen md:pl-60"><header className="flex h-16 items-center justify-between border-b border-gray-200 bg-white px-4 md:hidden"><span className="text-base font-semibold tracking-[0.16em]">ALTIX</span><button onClick={logout} title="Cerrar sesión" className="p-2 text-gray-500"><LogOut size={18} /></button></header><div className="border-b border-gray-200 bg-white px-4 py-3 md:hidden"><div className="flex gap-4 overflow-x-auto whitespace-nowrap text-sm">{mobileItems.map(([label, path]) => <Link key={path} to={path} className={location.pathname === path ? 'font-medium text-blue-700' : 'text-gray-500'}>{label}</Link>)}</div></div><main className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8"><Outlet /></main></div></div>;
};
